CREATE COLUMN TABLE "TEST_AP"."OSLM" ("DocID" INTEGER CS_INT NOT NULL , "DocDate" LONGDATE CS_LONGDATE, "Ref1" INTEGER CS_INT, "Ref2" INTEGER CS_INT, "Status" NVARCHAR(1), "DateFrom" LONGDATE CS_LONGDATE, "DateTo" LONGDATE CS_LONGDATE, "TotDebit" DECIMAL(21,6) CS_FIXED, "TotCredit" DECIMAL(21,6) CS_FIXED, "RateType" NVARCHAR(1) DEFAULT 'O', "Comment" NVARCHAR(250), "UserSign" SMALLINT CS_INT, "Canceled" NVARCHAR(1) DEFAULT 'N', "CancelDate" LONGDATE CS_LONGDATE, "CancelUser" SMALLINT CS_INT, PRIMARY KEY ("DocID")) UNLOAD PRIORITY 5  AUTO MERGE 